import argparse, json, os, sys, glob

def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def shape(obj):
    if isinstance(obj, dict):
        return {k: shape(obj[k]) for k in sorted(obj.keys())}
    if isinstance(obj, list):
        # Only shapes of dict/list vs scalar; ignore lengths
        return ["_list_" + ( "dict" if obj and isinstance(obj[0], dict) else "scalar_or_empty")]
    return "_scalar"

def compare_shapes(ref, other, path=""):
    errs = []
    if type(ref) != type(other):
        errs.append(f"type mismatch at {path or '/'}: {type(ref).__name__} vs {type(other).__name__}")
        return errs
    if isinstance(ref, dict):
        for k in ref:
            if k not in other:
                errs.append(f"missing key at {path or '/'}: {k}")
            else:
                errs.extend(compare_shapes(ref[k], other[k], f"{path}/{k}" if path else k))
        for k in other:
            if k not in ref:
                errs.append(f"extra key at {path or '/'}: {k}")
    elif isinstance(ref, list):
        tag_ref = shape(ref)
        tag_other = shape(other)
        if tag_ref != tag_other:
            errs.append(f"list shape mismatch at {path or '/'}: {tag_ref} vs {tag_other}")
    return errs

def main():
    ap = argparse.ArgumentParser(description="i18n JSON key/shape checker")
    ap.add_argument("--dir", required=True, help="Directory with locale JSON files (e.g., copy)")
    args = ap.parse_args()
    files = sorted(glob.glob(os.path.join(args.dir, "*.json")))
    if not files:
        print("No locale files found.", file=sys.stderr)
        sys.exit(2)
    # Use EN as reference if present; else first file
    ref_path = next((p for p in files if os.path.basename(p).startswith("en")), files[0])
    ref = load_json(ref_path)
    ok = True
    for p in files:
        if p == ref_path:
            continue
        other = load_json(p)
        errs = compare_shapes(ref, other)
        if errs:
            ok = False
            print(f"[FAIL] {os.path.basename(p)} vs {os.path.basename(ref_path)}")
            for e in errs:
                print(" -", e)
        else:
            print(f"[OK] {os.path.basename(p)}")
    sys.exit(0 if ok else 1)

if __name__ == "__main__":
    main()

