import glob, json, os, pytest

REQUIRED_VARIANTS = {"G", "R", "H"}
REQUIRED_KEYS_G = {"id","lang","strings"}
REQUIRED_KEYS_R = {"id","lang","strings"}
REQUIRED_KEYS_H = {"id","lang","strings"}
REQ_STRINGS_G = {"why","ask","preview_items","path_expert","cta"}
REQ_STRINGS_R = {"why","redirections","path_expert","cta"}
REQ_STRINGS_H = {"why","options","preview_items","cta"}

def load(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def dict_shape(d):
    if isinstance(d, dict):
        return {k: dict_shape(v) for k,v in sorted(d.items())}
    if isinstance(d, list):
        return ["list_dict" if (d and isinstance(d[0], dict)) else "list_scalar_or_empty"]
    return "scalar"

def test_copy_shapes_and_required_keys():
    files = sorted(glob.glob("copy/*.json"))
    assert files, "No locale files in copy/"
    ref = load(next((p for p in files if os.path.basename(p).startswith("en")), files[0]))
    ref_shape = dict_shape(ref)
    for p in files:
        obj = load(p)
        # Top-level variants present
        assert REQUIRED_VARIANTS.issubset(set(obj.keys())), f"Missing variants in {p}"
        # Per-variant basic keys and strings keys
        for vid in REQUIRED_VARIANTS:
            v = obj[vid]
            if vid == "G":
                assert REQUIRED_KEYS_G.issubset(v.keys())
                assert REQ_STRINGS_G.issubset(v["strings"].keys())
            if vid == "R":
                assert REQUIRED_KEYS_R.issubset(v.keys())
                assert REQ_STRINGS_R.issubset(v["strings"].keys())
            if vid == "H":
                assert REQUIRED_KEYS_H.issubset(v.keys())
                assert REQ_STRINGS_H.issubset(v["strings"].keys())
        # Shape parity with reference
        assert dict_shape(obj) == ref_shape, f"Shape mismatch vs reference in {p}"

